pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 mtFeeRate) public {
        // Restrict mtFeeRate to valid range for adjustMtFeeRate
        vm.assume(mtFeeRate <= 1e18);

        // Record the initial reserves
        (uint256 baseReserveBefore, uint256 quoteReserveBefore) = c.getVaultReserve();

        // Call adjustMtFeeRate
        c.adjustMtFeeRate(mtFeeRate);

        // Read reserves after the call
        (uint256 baseReserveAfter, uint256 quoteReserveAfter) = c.getVaultReserve();

        // The reserves must not have changed
        assertTrue(baseReserveBefore == baseReserveAfter && quoteReserveBefore == quoteReserveAfter, "Reserve changed after adjustMtFeeRate");
    }
}

