pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 mtFeeRate) public {
        // Restrict mtFeeRate to valid range
        vm.assume(mtFeeRate <= 10**18);

        // Record state before calling adjustMtFeeRate
        uint256 baseReserveBefore = c._BASE_RESERVE_();
        uint256 quoteReserveBefore = c._QUOTE_RESERVE_();

        // Call adjustMtFeeRate
        c.adjustMtFeeRate(mtFeeRate);

        // Read state after
        uint256 baseReserveAfter = c._BASE_RESERVE_();
        uint256 quoteReserveAfter = c._QUOTE_RESERVE_();

        // The reference contract never changes _QUOTE_RESERVE_ to equal _BASE_RESERVE_
        // unless they were already equal before the call and the bug doesn't trigger that.
        // The bug swaps in baseBalance for quoteBalance when updating _QUOTE_RESERVE_,
        // which can make them equal even if they weren't before.
        // Fix: add a bound to handle large mtFeeRate
        assertTrue(
            quoteReserveAfter == quoteReserveBefore || 
            (quoteReserveAfter != baseReserveAfter && quoteReserveAfter != baseReserveBefore)
        );
    }
}

