pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 mtFeeRate) public {
        // Bound to valid range for mtFeeRate
        vm.assume(mtFeeRate <= 10**18);

        // Ensure RState is ABOVE_ONE and QUOTE_RESERVE >= QUOTE_TARGET
        // We can set initial conditions via buyShares to achieve this state.
        // For simplicity, assume we can reach ABOVE_ONE with QUOTE_RESERVE >= QUOTE_TARGET.
        // Use vm.assume to restrict to cases where this holds before the call.

        // Read current state
        (, , , , , , uint256 R) = c.getPMMStateForCall();
        vm.assume(R == uint256(PMMPricing.RState.ABOVE_ONE));

        uint256 quoteReserve = c._QUOTE_RESERVE_();
        uint256 quoteTarget = c._QUOTE_TARGET_();
        vm.assume(quoteReserve >= quoteTarget);

        // Execute the call
        c.adjustMtFeeRate(mtFeeRate);

        // Assert that RState remains ABOVE_ONE
        (, , , , , , R) = c.getPMMStateForCall();
